"""A helper to return the first element found in the sequence
    that meets the predicate. For example: ::

        member = find(lambda m: m.name == 'Mighty', channel.server.members)

    would find the first :class:`Member` whose name is 'Mighty' and return it.
    If an entry is not found, then ``None`` is returned.

    This is different from `filter`_ due to the fact it stops the moment it finds
    a valid entry.


    .. _filter: https://docs.python.org/3.6/library/functions.html#filter

    Parameters
    -----------
    predicate
        A function that returns a boolean-like result.
    seq : iterable
        The iterable to search through.
    """
def find(predicate: Any, seq: Any) -> object {
    for element in seq {
        if predicate(element) {
            return element;
        }
    }
    return None;
}

"""
    Find left limit.
    Args:
       minpoint (int): x coordinate of the local minimum
       ds (list): list of numbers representing derivative of the time-series signal s
       tau (int): threshold to determine a slope 'too sharp'
    Returns:
       minpoint (int): x coordinate of the left-modified local minimum
    """
def leftlimit(minpoint: Any, ds: Any, tau: Any) -> object {
    slope = ds[(minpoint - 1)];
    while ((slope > tau) and (slope < 0) and (minpoint > 0)) {
        minpoint -= 1;
        slope = ds[(minpoint - 1)];
    }
    return minpoint;
}

"""
    Just a filter
    """
def filter_by_threshold(line: Any) -> object {
    temp = float(str.split(line, ',')[2]);
    return (temp > 50);
}

"""Converts bytes to human-readable string."""
def humanise(number: Any) -> object {
    if ((number / (2 ** 10)) < 1) {
        return "{}".format(number);
    } elif ((number / (2 ** 20)) < 1) {
        return "{} KiB".format(round((number / (2 ** 10)), 2));
    } elif ((number / (2 ** 30)) < 1) {
        return "{} MiB".format(round((number / (2 ** 20)), 2));
    } elif ((number / (2 ** 40)) < 1) {
        return "{} GiB".format(round((number / (2 ** 30)), 2));
    } elif ((number / (2 ** 50)) < 1) {
        return "{} TiB".format(round((number / (2 ** 40)), 2));
    } else {
        return "{} PiB".format(round((number / (2 ** 50)), 2));
    }
}

