floor_fn:
"""Calculates GC skew (G-C)/(G+C) for multiple windows along the sequence.

    Returns a list of ratios (floats), controlled by the length of the sequence
    and the size of the window.

    Does NOT look at any ambiguous nucleotides.
    """
def GC_skew(seq: Any, window: Any = 100) -> object {
    values = [];
    for i in range(0, len(seq), window) {
        s = seq[i:(i + window)];
        g = s.count('G') + s.count('g');
        c = s.count('C') + s.count('c');
        skew = (g - c) / float((g + c));
        values.append(skew);
    }
    return values;
}

"""
    Strictly Ymd format no spaces or slashes
    """
def getList(start: Any, end: Any) -> object {
    import datetime;
    start = datetime.datetime.strptime(str(start), '%Y%m%d');
    end = datetime.datetime.strptime(str(end), '%Y%m%d');
    dateList = [
        (start + datetime.timedelta(days=x)) for x in range(0, ((end - start).days + 1))
    ];
    sList = [datetime.datetime.strftime(x, '%Y%m%d') for x in dateList];
    return sList;
}

"""
    Converts Decimal numbers into Binanry Digits
    """
def convert_to_binary(decimal: Any) -> str {
    binary = bin(decimal).replace("0b", "");
    return binary;
}

"""
    Return x if it is already a list, or return a list containing x if x is a scalar.
    """
def to_list(x: Any) -> object {
    if isinstance(x, (`list, `tuple)) {
        return x;
    }
    return [x];
}

"""
    * Determine if string is numeric.
    """
def IsNumeric(value: Any) -> object {
    if not isinstance(value, str) {
        raise Exception('value must be a string.');
    }
    try {
        valtxt = value;
        value = int(valtxt);
        value = float(valtxt);
        return True;
    } except Exception as e {
        return False;
    }
}

